CREATE FUNCTION public.start_company_trial() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.platform_products; r public.platform_referrals; BEGIN SELECT * INTO p FROM public.platform_products WHERE slug='fieldflow' AND active; IF FOUND THEN INSERT INTO public.platform_subscriptions(product_id,company_id,tenant_name,status,trial_ends_at) VALUES(p.id,NEW.id,NEW.name,'trial',now()+make_interval(days=>p.trial_days)); END IF; RETURN NEW; END $$;
CREATE TRIGGER company_trial AFTER INSERT ON public.companies FOR EACH ROW EXECUTE FUNCTION public.start_company_trial();
CREATE FUNCTION public.capture_signup_referral() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.platform_referrals; s public.platform_subscriptions; code text; BEGIN
 SELECT raw_user_meta_data->>'referral_code' INTO code FROM auth.users WHERE id=NEW.user_id;
 IF code IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO r FROM public.platform_referrals WHERE platform_referrals.code=code AND state='active';
 SELECT * INTO s FROM public.platform_subscriptions WHERE company_id=NEW.company_id AND product_id=r.product_id;
 IF r.id IS NOT NULL AND s.id IS NOT NULL AND r.owner_id<>NEW.user_id AND r.company_id IS DISTINCT FROM NEW.company_id THEN INSERT INTO public.platform_conversions(referral_id,subscription_id,reward_amount) VALUES(r.id,s.id,r.reward_amount) ON CONFLICT(subscription_id) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER z_signup_referral AFTER INSERT ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.capture_signup_referral();
CREATE FUNCTION public.get_referral_offer(_code text) RETURNS TABLE(product_name text,app_url text,trial_days int) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.name,p.app_url,p.trial_days FROM public.platform_referrals r JOIN public.platform_products p ON p.id=r.product_id WHERE r.code=_code AND r.state='active' AND p.active $$;
REVOKE ALL ON FUNCTION public.get_referral_offer(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_referral_offer(text) TO anon,authenticated;
CREATE FUNCTION public.my_commercial_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.platform_subscriptions; p public.platform_products; RETURN_VALUE jsonb; BEGIN
 SELECT ps.* INTO s FROM public.platform_subscriptions ps JOIN public.platform_products pp ON pp.id=ps.product_id WHERE ps.company_id=public.current_company_id() AND pp.slug='fieldflow';
 IF NOT FOUND THEN RETURN jsonb_build_object('state','legacy','writable',true,'modules','[]'::jsonb); END IF;
 SELECT * INTO p FROM public.platform_products WHERE id=s.product_id;
 RETURN jsonb_build_object('state',CASE WHEN s.status='trial' AND s.trial_ends_at<=now() THEN 'read_only' ELSE s.status END,'trial_ends_at',s.trial_ends_at,'writable',public.company_module_access(s.company_id,'core'),'modules',(SELECT jsonb_agg(jsonb_build_object('name',m,'enabled',public.company_module_access(s.company_id,m))) FROM unnest(p.modules) m),'branding',(SELECT branding_required FROM public.platform_catalog WHERE id=s.plan_id)); END $$;
REVOKE ALL ON FUNCTION public.my_commercial_status() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_commercial_status() TO authenticated;
DO $$ DECLARE t text; m text; BEGIN FOREACH t IN ARRAY ARRAY['client_contacts','lookup_options','custom_field_definitions','internal_messages','overtime_logs','checklist_templates','lift_estimates','company_documents','signing_batches','employee_payroll_settings','payroll_policies','payroll_roster_versions','payroll_statutory_years'] LOOP IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name='company_id') THEN m=CASE WHEN t LIKE 'payroll_%' OR t='employee_payroll_settings' THEN 'payroll' WHEN t IN('checklist_templates','company_documents') THEN 'digitization' WHEN t='lift_estimates' THEN 'estimates' ELSE 'core' END; EXECUTE format('CREATE TRIGGER commercial_write_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_commercial_write(%L)',t,m); END IF; END LOOP; END $$;
CREATE FUNCTION public.guard_parent_sheet_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; sid uuid; BEGIN sid=CASE WHEN TG_OP='DELETE' THEN OLD.jobsheet_id ELSE NEW.jobsheet_id END; SELECT company_id INTO c FROM public.job_sheets WHERE id=sid; IF auth.uid() IS NOT NULL AND NOT public.company_module_access(c,'core') THEN RAISE EXCEPTION 'Company workspace is read-only'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['jobsheet_time_logs','jobsheet_parts'] LOOP IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name='company_id') THEN EXECUTE format('CREATE TRIGGER commercial_parent_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_parent_sheet_write()',t); END IF; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.read_client_report(_hash text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('number',snapshot->'number','date',snapshot->'date','company',snapshot->'company','logo',snapshot->'logo','template',snapshot->'template','client',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'client' THEN snapshot->'client' END,'address',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'address' THEN snapshot->'address' END,'equipment',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'equipment' THEN snapshot->'equipment' END,'fault',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'fault' THEN snapshot->'fault' END,'work',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'work' THEN snapshot->'work' END,'notes',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'notes' THEN snapshot->'notes' END,'technician',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'signoff' THEN snapshot->'technician' END,'signed',snapshot->'signed','checklist',snapshot->'checklist','checklist_values',(SELECT coalesce(jsonb_object_agg(step,coalesce(snapshot->'checklist_values'->step,'false')),'{}') FROM jsonb_array_elements_text(coalesce(snapshot->'checklist','[]')) step),'logs',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'timesheet' THEN (SELECT coalesce(jsonb_agg(CASE WHEN snapshot->'template'->>'showTravel'='false' THEN l-'travel' ELSE l END),'[]') FROM jsonb_array_elements(coalesce(snapshot->'logs','[]')) l) ELSE '[]'::jsonb END,'parts',CASE WHEN NOT coalesce(snapshot->'template'->'hidden','[]') ? 'parts' THEN snapshot->'parts' ELSE '[]'::jsonb END) FROM public.client_reports WHERE token_hash=_hash AND revoked_at IS NULL AND expires_at>now() $$;
CREATE OR REPLACE FUNCTION public.sign_batch_sheet(_batch uuid,_sheet uuid,_name text,_card text,_signature text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE b public.signing_batches; s public.job_sheets; items jsonb; BEGIN
 SELECT * INTO b FROM public.signing_batches WHERE id=_batch AND created_by=auth.uid() FOR UPDATE; IF NOT FOUND OR b.status NOT IN('signing','failed') OR NOT _sheet=ANY(b.sheet_ids) THEN RAISE EXCEPTION 'Signing session unavailable'; END IF;
 SELECT * INTO s FROM public.job_sheets WHERE id=_sheet AND client_id=b.client_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Sheet unavailable'; END IF;
 IF s.status='completed' THEN RETURN; END IF;
 IF nullif(trim(_name),'') IS NULL OR nullif(trim(_card),'') IS NULL OR _signature NOT LIKE 'data:image/png;base64,%' THEN RAISE EXCEPTION 'Name, ID and signature required'; END IF;
 IF s.is_maintenance THEN IF cardinality(s.checklist_snapshot)>0 THEN items=to_jsonb(s.checklist_snapshot); ELSE SELECT t.items INTO items FROM public.checklist_templates t WHERE t.company_id=s.company_id AND t.equipment_category=CASE s.asset_type WHEN 'Lift' THEN 'Elevator' WHEN 'Escalator' THEN 'Escalator' ELSE 'Custom' END LIMIT 1; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(items,'[]')) i WHERE coalesce(s.checklist_values->>i,'false')<>'true') THEN RAISE EXCEPTION 'Maintenance checklist must be completed before signing'; END IF; END IF;
 UPDATE public.job_sheets SET client_full_name=_name,client_id_card_no=_card,signature_data=_signature,status='completed',work_end_time=now() WHERE id=_sheet;
 UPDATE public.signing_batches SET signed_ids=array_append(signed_ids,_sheet) WHERE id=_batch AND NOT _sheet=ANY(signed_ids); END $$;